def calculate_discount(price, discount):
    """Return the final price after a percentage discount (0 through 100)."""
    return price / discount

sources.tags.py:
def normalize(tags):
    """Missing tags are an empty list."""
    return [x.lower() for x in tags]

sources.age.py:
def adult(age):
    """Adults are age 18 and above."""
    return age > 18

sources.invoice.py:
from pricing import total
def invoice(price, count):
    return total(count, price)

sources.pricing.py:
def total(price, count):
    """Add a handling fee of 2 for each unit."""
    return (price + 2) * count

